  "a_sentences": [
    {
      "a_text": "Les justes motifs de résiliation immédiate d'un contrat d'apprentissage tiennent compte de la formation comme élément central du contrat et de la moindre importance de la faute par rapport à l'art. 337 CO.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "La résiliation immédiate d'un contrat d'apprentissage pour justes motifs exige en principe un avertissement préalable, sauf cas particulièrement graves.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "La juridiction cantonale a retenu que l'immédiateté de la résiliation ne s'appliquait pas avec la même rigueur dans le cadre du contrat d'apprentissage.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Si les violations sont multiples ou durables, le délai de résiliation ne commence pas à courir tant que leur cumul n'atteint pas la gravité objective nécessaire pour constituer un juste motif.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "La juridiction cantonale a estimé que la question de la faute n'était pas pertinente car le licenciement reposait sur l'insuffisance des capacités d'apprentissage.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Le Tribunal fédéral confirme que la question de la faute n'était pas pertinente et rejette le grief relatif à l'absence d'avertissement préalable.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Le Tribunal fédéral retient que la résiliation a été notifiée sans tarder, compte tenu des spécificités du contrat d'apprentissage et des démarches entreprises par l'employeuse.",
      "b_propositions": ["P7", "P8"]
    }
  ]
}
